  9	import com.pousadamarealta.service.*;
 10	import com.pousadamarealta.util.Config;
 11	import com.zaxxer.hikari.HikariConfig;
 12	import com.zaxxer.hikari.HikariDataSource;
 13	import io.javalin.Javalin;
 14	import io.javalin.json.JavalinJackson;
 15	
 16	import javax.sql.DataSource;
 17	import java.util.ArrayList;
 18	import java.util.List;
 19	
 20	public class App {
 21	
 22	    public static void main(String[] args) {
 23	        DataSource dataSource = createDataSource();
 24	
 25	        DatabaseInitializer dbInitializer = new DatabaseInitializer(dataSource);
 26	        dbInitializer.initialize();
 27	
 28	        RoomRepository roomRepository = new RoomRepository(dataSource);
 29	        ReservationRepository reservationRepository = new ReservationRepository(dataSource);
 30	        MessageRepository messageRepository = new MessageRepository(dataSource);
 31	
 32	        roomRepository.initializeRooms();
 33	
 34	        MessageProcessor messageProcessor = createMessageProcessor();
 35	
 36	        RoomService roomService = new RoomService(roomRepository);
 37	        MessageService messageService = new MessageService(messageRepository);
 38	        ReservationService reservationService = new ReservationService(
 39	            reservationRepository,
 40	            messageRepository,
 41	            roomService,
 42	            messageProcessor
 43	        );
 44	        OccupancyReportService occupancyReportService = new OccupancyReportService(
 45	            reservationService,
 46	            roomService
 47	        );
 48	        RevenueReportService revenueReportService = new RevenueReportService(reservationService);
 49	
 50	        RoomController roomController = new RoomController(roomService);
 51	        ReservationController reservationController = new ReservationController(reservationService, roomService);
 52	        MessageController messageController = new MessageController(messageService);
 53	        ReportController reportController = new ReportController(occupancyReportService, revenueReportService);
 54	
 55	        int port = getPort();
 56	
 57	        Javalin app = Javalin.create(config -> {
 58	            ObjectMapper mapper = new ObjectMapper();
 59	            mapper.registerModule(new JavaTimeModule());
 60	            mapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 61	            config.jsonMapper(new JavalinJackson(mapper, true));
 62	        }).start(port);
 63	
 64	        app.get("/rooms", roomController::getAllRooms);
 65	        app.post("/reservations", reservationController::createReservation);
 66	        app.get("/reservations/{id}", reservationController::getReservation);
 67	        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
 68	        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
 69	        app.post("/reservations/{id}/check-in", reservationController::checkIn);
 70	        app.post("/reservations/{id}/check-out", reservationController::checkOut);
 71	        app.get("/reservations/{id}/document", reservationController::getDocument);
 72	        app.get("/messages", messageController::getAllMessages);
 73	        app.get("/reports/occupancy", reportController::getOccupancyReport);
 74	        app.get("/reports/revenue", reportController::getRevenueReport);
 75	
 76	        ExceptionHandler.register(app);
 77	    }
 78	
 79	    private static DataSource createDataSource() {
 80	        String url = Config.get("DB_URL");
 81	        String user = Config.get("DB_USER");
 82	        String password = Config.get("DB_PASSWORD");
 83	
 84	        if (url == null || user == null || password == null) {
 85	            throw new IllegalStateException("Database configuration missing");
 86	        }
 87	
 88	        HikariConfig config = new HikariConfig();
 89	        config.setJdbcUrl(url);
 90	        config.setUsername(user);
 91	        config.setPassword(password);
 92	        config.setMaximumPoolSize(10);
 93	
 94	        return new HikariDataSource(config);
 95	    }
 96	
 97	    private static MessageProcessor createMessageProcessor() {
 98	        List<MessageRule> rules = new ArrayList<>();
 99	
100	        rules.add(new EmailValidationRule());
101	
102	        boolean testMode = "true".equalsIgnoreCase(Config.get("HOTEL_TEST_MODE"));
103	
104	        if (testMode) {
105	            rules.add(new TestModeRule(true));
106	        } else {
107	            rules.add(new ArchiveCopyRule());
108	        }
109	
110	        return new MessageProcessor(rules);
111	    }
112	
113	    private static int getPort() {
114	        String portEnv = Config.get("PORT");
115	        if (portEnv != null && !portEnv.isEmpty()) {
116	            return Integer.parseInt(portEnv);
117	        }
118	        return 7070;
119	    }
120	}
