127	import io.javalin.validation.ValidationException;
128	
129	import java.time.format.DateTimeParseException;
130	
131	public class ExceptionHandler {
132	
133	    public static void register(io.javalin.Javalin app) {
134	        app.exception(ValidationException.class, (e, ctx) -> {
135	            ctx.status(400).json(new ErrorDTO("INVALID_REQUEST", "Invalid request parameters"));
136	        });
137	
138	        app.exception(JsonProcessingException.class, (e, ctx) -> {
139	            ctx.status(400).json(new ErrorDTO("INVALID_REQUEST", "Invalid JSON format"));
140	        });
141	
142	        app.exception(DateTimeParseException.class, (e, ctx) -> {
143	            ctx.status(400).json(new ErrorDTO("INVALID_REQUEST", "Invalid date format"));
144	        });
145	
146	        app.exception(IllegalArgumentException.class, (e, ctx) -> {
147	            ctx.status(400).json(new ErrorDTO("INVALID_REQUEST", e.getMessage()));
148	        });
149	
150	        app.exception(RoomNotFoundException.class, (e, ctx) -> {
151	            ctx.status(404).json(new ErrorDTO("ROOM_NOT_FOUND", e.getMessage()));
152	        });
153	
154	        app.exception(ReservationNotFoundException.class, (e, ctx) -> {
155	            ctx.status(404).json(new ErrorDTO("RESERVATION_NOT_FOUND", e.getMessage()));
156	        });
157	
158	        app.exception(RoomUnavailableException.class, (e, ctx) -> {
159	            ctx.status(409).json(new ErrorDTO("ROOM_UNAVAILABLE", e.getMessage()));
160	        });
161	
162	        app.exception(OperationNotAllowedException.class, (e, ctx) -> {
163	            ctx.status(409).json(new ErrorDTO("OPERATION_NOT_ALLOWED", e.getMessage()));
164	        });
165	
166	        app.exception(CapacityExceededException.class, (e, ctx) -> {
167	            ctx.status(422).json(new ErrorDTO("CAPACITY_EXCEEDED", e.getMessage()));
168	        });
169	
170	        app.exception(IllegalStateException.class, (e, ctx) -> {
171	            ctx.status(409).json(new ErrorDTO("OPERATION_NOT_ALLOWED", e.getMessage()));
172	        });
173	    }
174	}
