232	import com.pousadamarealta.domain.RatePlan;
233	import com.pousadamarealta.domain.Reservation;
234	import com.pousadamarealta.domain.Room;
235	import com.pousadamarealta.dto.CreateReservationDTO;
236	import com.pousadamarealta.dto.DocumentDTO;
237	import com.pousadamarealta.dto.ReservationDTO;
238	import com.pousadamarealta.service.ReservationService;
239	import com.pousadamarealta.service.RoomService;
240	import com.pousadamarealta.util.RequestValidator;
241	import io.javalin.http.Context;
242	
243	import java.time.LocalDate;
244	
245	public class ReservationController {
246	    private final ReservationService reservationService;
247	    private final RoomService roomService;
248	
249	    public ReservationController(ReservationService reservationService, RoomService roomService) {
250	        this.reservationService = reservationService;
251	        this.roomService = roomService;
252	    }
253	
254	    public void createReservation(Context ctx) {
255	        CreateReservationDTO dto = ctx.bodyAsClass(CreateReservationDTO.class);
256	        RequestValidator.validateCreateReservation(dto);
257	
258	        LocalDate checkIn = LocalDate.parse(dto.checkIn());
259	        LocalDate checkOut = LocalDate.parse(dto.checkOut());
260	        RatePlan ratePlan = RatePlan.valueOf(dto.ratePlan());
261	
262	        Reservation reservation = reservationService.createReservation(
263	            dto.roomNumber(),
264	            dto.guestName(),
265	            dto.guestEmail(),
266	            dto.guestCpf(),
267	            checkIn,
268	            checkOut,
269	            dto.guests(),
270	            ratePlan
271	        );
272	
273	        Room room = roomService.getRoomByNumber(reservation.getRoomNumber());
274	        ctx.status(201).json(ReservationDTO.from(reservation, room));
275	    }
276	
277	    public void getReservation(Context ctx) {
278	        long id = Long.parseLong(ctx.pathParam("id"));
279	        Reservation reservation = reservationService.getReservation(id);
280	        Room room = roomService.getRoomByNumber(reservation.getRoomNumber());
281	        ctx.json(ReservationDTO.from(reservation, room));
282	    }
283	
284	    public void confirmReservation(Context ctx) {
285	        long id = Long.parseLong(ctx.pathParam("id"));
286	        Reservation reservation = reservationService.confirmReservation(id);
287	        Room room = roomService.getRoomByNumber(reservation.getRoomNumber());
288	        ctx.json(ReservationDTO.from(reservation, room));
289	    }
290	
291	    public void checkIn(Context ctx) {
292	        long id = Long.parseLong(ctx.pathParam("id"));
293	        Reservation reservation = reservationService.checkIn(id);
294	        Room room = roomService.getRoomByNumber(reservation.getRoomNumber());
295	        ctx.json(ReservationDTO.from(reservation, room));
296	    }
297	
298	    public void checkOut(Context ctx) {
299	        long id = Long.parseLong(ctx.pathParam("id"));
300	        Reservation reservation = reservationService.checkOut(id);
301	        Room room = roomService.getRoomByNumber(reservation.getRoomNumber());
302	        ctx.json(DocumentDTO.from(reservation, room));
303	    }
304	
305	    public void cancelReservation(Context ctx) {
306	        long id = Long.parseLong(ctx.pathParam("id"));
307	        Reservation reservation = reservationService.cancelReservation(id);
308	        Room room = roomService.getRoomByNumber(reservation.getRoomNumber());
309	        ctx.json(ReservationDTO.from(reservation, room));
310	    }
311	
312	    public void getDocument(Context ctx) {
313	        long id = Long.parseLong(ctx.pathParam("id"));
314	        Reservation reservation = reservationService.getReservation(id);
315	        Room room = roomService.getRoomByNumber(reservation.getRoomNumber());
316	
317	        if (reservation.getAmountPaid().signum() == 0) {
318	            throw new IllegalStateException("Document only available for paid reservations");
319	        }
320	
321	        ctx.json(DocumentDTO.from(reservation, room));
322	    }
323	}
