363	package com.pousadamarealta.util;
364	
365	import com.pousadamarealta.dto.CreateReservationDTO;
366	
367	import java.time.LocalDate;
368	
369	public class RequestValidator {
370	
371	    public static void validateCreateReservation(CreateReservationDTO dto) {
372	        if (dto.roomNumber() == null || dto.roomNumber().isEmpty()) {
373	            throw new IllegalArgumentException("roomNumber is required");
374	        }
375	        if (dto.guestName() == null || dto.guestName().isEmpty()) {
376	            throw new IllegalArgumentException("guestName is required");
377	        }
378	        if (dto.guestEmail() == null || dto.guestEmail().isEmpty()) {
379	            throw new IllegalArgumentException("guestEmail is required");
380	        }
381	        if (dto.guestCpf() == null || dto.guestCpf().isEmpty()) {
382	            throw new IllegalArgumentException("guestCpf is required");
383	        }
384	        if (dto.checkIn() == null || dto.checkIn().isEmpty()) {
385	            throw new IllegalArgumentException("checkIn is required");
386	        }
387	        if (dto.checkOut() == null || dto.checkOut().isEmpty()) {
388	            throw new IllegalArgumentException("checkOut is required");
389	        }
390	        if (dto.ratePlan() == null || dto.ratePlan().isEmpty()) {
391	            throw new IllegalArgumentException("ratePlan is required");
392	        }
393	
394	        LocalDate checkIn = LocalDate.parse(dto.checkIn());
395	        LocalDate checkOut = LocalDate.parse(dto.checkOut());
396	
397	        if (!checkOut.isAfter(checkIn)) {
398	            throw new IllegalArgumentException("checkOut must be after checkIn");
399	        }
400	
401	        if (dto.guests() < 1) {
402	            throw new IllegalArgumentException("guests must be at least 1");
403	        }
404	    }
405	}

