 30	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
 31	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
 32	                                        int guests, RatePlan ratePlan) {
 33	        Room room = roomService.getRoomByNumber(roomNumber);
 34	
 35	        if (guests > room.getCapacity()) {
 36	            throw new CapacityExceededException();
 37	        }
 38	
 39	        if (reservationRepository.hasConflict(roomNumber, checkIn, checkOut, null)) {
 40	            throw new RoomUnavailableException();
 41	        }
 42	
 43	        Reservation reservation = new Reservation(
 44	            roomNumber, guestName, guestEmail, guestCpf,
 45	            checkIn, checkOut, guests, ratePlan
 46	        );
 47	
 48	        return reservationRepository.save(reservation);
 49	    }
