 56	    public Reservation confirmReservation(Long id) {
 57	        Reservation reservation = getReservation(id);
 58	        Room room = roomService.getRoomByNumber(reservation.getRoomNumber());
 59	
 60	        try {
 61	            reservation.confirm(room.getNightlyRate());
 62	        } catch (IllegalStateException e) {
 63	            throw new OperationNotAllowedException(e.getMessage());
 64	        }
 65	
 66	        Reservation saved = reservationRepository.save(reservation);
 67	        sendConfirmationEmail(saved, room);
 68	
 69	        return saved;
 70	    }
