111	        if (reservation.getStatus() == ReservationStatus.PENDING) {
112	            throw new OperationNotAllowedException("Document only available for confirmed reservations");
113	        }
114	
115	        Room room = roomService.getRoomByNumber(reservation.getRoomNumber());
116	        return formatDocument(reservation, room);
117	    }
