119	    private void sendConfirmationEmail(Reservation reservation, Room room) {
120	        String document = formatDocument(reservation, room);
121	
122	        String body = String.format("""
123	            Olá, %s!
124	
125	            Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
126	
127	            %s
128	
129	            A entrada é a partir das 14h, e a saída, até as 12h.
130	            Até breve!
131	            """, reservation.getGuestName(), document);
132	
133	        Message message = new Message(
134	            MessageChannel.EMAIL,
135	            reservation.getGuestEmail(),
136	            "Reserva confirmada - Pousada Maré Alta",
137	            body
138	        );
139	
140	        List<Message> processedMessages = messageProcessor.process(message);
141	
142	        for (Message msg : processedMessages) {
143	            messageRepository.save(msg);
144	        }
145	    }
146	
147	    private String formatDocument(Reservation reservation, Room room) {
148	        DateTimeFormatter dateFormatter = DateTimeFormatter.ofPattern("dd/MM/yyyy");
149	        BigDecimal subtotal = reservation.getSubtotal(room.getNightlyRate());
150	        BigDecimal discount = reservation.getDiscount(subtotal);
151	        BigDecimal total = reservation.getTotal(room.getNightlyRate());
152	
153	        int nights = reservation.getNights();
154	        String nightsText = nights == 1 ? "1 diária" : nights + " diárias";
155	
156	        StringBuilder doc = new StringBuilder();
157	        doc.append(String.format("Comprovante de reserva nº %d\n", reservation.getId()));
158	        doc.append(String.format("Hóspede: %s (CPF %s)\n",
159	            reservation.getGuestName(), formatCpf(reservation.getGuestCpf())));
160	        doc.append(String.format("Quarto: %s (%s)\n",
161	            reservation.getRoomNumber(), room.getType().name()));
162	        doc.append(String.format("Entrada: %s | Saída: %s | %s\n",
163	            reservation.getCheckIn().format(dateFormatter),
164	            reservation.getCheckOut().format(dateFormatter),
165	            nightsText));
166	        doc.append(String.format("Diárias: %s\n", formatMoney(subtotal)));
167	
168	        if (discount.compareTo(BigDecimal.ZERO) > 0) {
169	            doc.append(String.format("Desconto: %s\n", formatMoney(discount)));
170	        }
171	
172	        doc.append(String.format("Total: %s", formatMoney(total)));
173	
174	        return doc.toString();
175	    }
176	
177	    private String formatCpf(String cpf) {
178	        if (cpf.length() == 11) {
179	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
180	                   cpf.substring(6, 9) + "-" + cpf.substring(9);
181	        }
182	        return cpf;
183	    }
184	
185	    private String formatMoney(BigDecimal amount) {
186	        return String.format("R$ %,.2f", amount).replace(",", "X").replace(".", ",").replace("X", ".");
187	    }
