267	public class RevenueReportService {
268	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
269	
270	    private final ReservationService reservationService;
271	
272	    public RevenueReportService(ReservationService reservationService) {
273	        this.reservationService = reservationService;
274	    }
275	
276	    public String generateReport(YearMonth month) {
277	        List<Reservation> reservations = reservationService.getReservationsByMonth(month);
278	
279	        StringBuilder csv = new StringBuilder();
280	        csv.append("reservation,room,check_in,check_out,status,amount\n");
281	
282	        BigDecimal total = BigDecimal.ZERO;
283	
284	        for (Reservation reservation : reservations) {
285	            BigDecimal netAmount = calculateNetAmount(reservation);
286	
287	            csv.append(String.format("%d,%s,%s,%s,%s,%.2f\n",
288	                reservation.getId(),
289	                reservation.getRoomNumber(),
290	                reservation.getCheckIn().format(DATE_FORMAT),
291	                reservation.getCheckOut().format(DATE_FORMAT),
292	                reservation.getStatus().name(),
293	                netAmount
294	            ));
295	
296	            total = total.add(netAmount);
297	        }
298	
299	        csv.append(String.format("total,%.2f", total));
300	
301	        return csv.toString();
302	    }
303	
304	    private BigDecimal calculateNetAmount(Reservation reservation) {
305	        BigDecimal paid = reservation.getAmountPaid();
306	        BigDecimal refund = reservation.getRefund() != null ? reservation.getRefund() : BigDecimal.ZERO;
307	        return paid.subtract(refund);
308	    }
309	}
