  2	
  3	import java.math.BigDecimal;
  4	import java.math.RoundingMode;
  5	import java.time.LocalDate;
  6	import java.time.temporal.ChronoUnit;
  7	
  8	public class Reservation {
  9	    private Long id;
 10	    private final String roomNumber;
 11	    private final String guestName;
 12	    private final String guestEmail;
 13	    private final String guestCpf;
 14	    private final LocalDate checkIn;
 15	    private final LocalDate checkOut;
 16	    private final int guests;
 17	    private final RatePlan ratePlan;
 18	    private ReservationStatus status;
 19	    private BigDecimal amountPaid;
 20	    private BigDecimal refund;
 21	
 22	    public Reservation(String roomNumber, String guestName, String guestEmail, String guestCpf,
 23	                       LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
 24	        this.roomNumber = roomNumber;
 25	        this.guestName = guestName;
 26	        this.guestEmail = guestEmail;
 27	        this.guestCpf = guestCpf;
 28	        this.checkIn = checkIn;
 29	        this.checkOut = checkOut;
 30	        this.guests = guests;
 31	        this.ratePlan = ratePlan;
 32	        this.status = ReservationStatus.PENDING;
 33	        this.amountPaid = BigDecimal.ZERO;
 34	        this.refund = null;
 35	    }
 36	
 37	    public Reservation(Long id, String roomNumber, String guestName, String guestEmail, String guestCpf,
 38	                       LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan,
 39	                       ReservationStatus status, BigDecimal amountPaid, BigDecimal refund) {
 40	        this.id = id;
 41	        this.roomNumber = roomNumber;
 42	        this.guestName = guestName;
 43	        this.guestEmail = guestEmail;
 44	        this.guestCpf = guestCpf;
 45	        this.checkIn = checkIn;
 46	        this.checkOut = checkOut;
 47	        this.guests = guests;
 48	        this.ratePlan = ratePlan;
 49	        this.status = status;
 50	        this.amountPaid = amountPaid;
 51	        this.refund = refund;
 52	    }
 53	
 54	    public int getNights() {
 55	        return (int) ChronoUnit.DAYS.between(checkIn, checkOut);
 56	    }
 57	
 58	    public BigDecimal getSubtotal(BigDecimal nightlyRate) {
 59	        BigDecimal sum = BigDecimal.ZERO;
 60	        LocalDate date = checkIn;
 61	
 62	        while (date.isBefore(checkOut)) {
 63	            BigDecimal nightPrice = nightlyRate;
 64	            if (SeasonCalculator.isHighSeason(date)) {
 65	                nightPrice = nightPrice.multiply(new BigDecimal("1.20"))
 66	                    .setScale(2, RoundingMode.HALF_EVEN);
 67	            }
 68	            sum = sum.add(nightPrice);
 69	            date = date.plusDays(1);
 70	        }
 71	
 72	        return sum.setScale(2, RoundingMode.HALF_EVEN);
 73	    }
 74	
 75	    public BigDecimal getDiscount(BigDecimal subtotal) {
 76	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
 77	            return subtotal.multiply(new BigDecimal("0.15"))
 78	                .setScale(2, RoundingMode.HALF_EVEN);
 79	        }
 80	        return BigDecimal.ZERO;
 81	    }
 82	
 83	    public BigDecimal getTotal(BigDecimal nightlyRate) {
 84	        BigDecimal subtotal = getSubtotal(nightlyRate);
 85	        BigDecimal discount = getDiscount(subtotal);
 86	        return subtotal.subtract(discount).setScale(2, RoundingMode.HALF_EVEN);
 87	    }
 88	
 89	    public void confirm(BigDecimal nightlyRate) {
 90	        if (status != ReservationStatus.PENDING) {
 91	            throw new IllegalStateException("Only pending reservations can be confirmed");
 92	        }
 93	        this.status = ReservationStatus.CONFIRMED;
 94	        this.amountPaid = getTotal(nightlyRate);
 95	    }
 96	
