  2	
  3	import javax.sql.DataSource;
  4	import java.sql.Connection;
  5	import java.sql.Statement;
  6	
  7	public class DatabaseInitializer {
  8	    private final DataSource dataSource;
  9	
 10	    public DatabaseInitializer(DataSource dataSource) {
 11	        this.dataSource = dataSource;
 12	    }
 13	
 14	    public void initialize() {
 15	        createTables();
 16	    }
 17	
 18	    private void createTables() {
 19	        String sql = """
 20	            CREATE TABLE IF NOT EXISTS rooms (
 21	                number VARCHAR(10) PRIMARY KEY,
 22	                type VARCHAR(20) NOT NULL
 23	            );
 24	
 25	            CREATE TABLE IF NOT EXISTS reservations (
 26	                id BIGSERIAL PRIMARY KEY,
 27	                room_number VARCHAR(10) NOT NULL REFERENCES rooms(number),
 28	                guest_name VARCHAR(255) NOT NULL,
 29	                guest_email VARCHAR(255) NOT NULL,
 30	                guest_cpf VARCHAR(14) NOT NULL,
 31	                check_in DATE NOT NULL,
 32	                check_out DATE NOT NULL,
 33	                guests INTEGER NOT NULL,
 34	                rate_plan VARCHAR(20) NOT NULL,
 35	                status VARCHAR(20) NOT NULL,
 36	                amount_paid DECIMAL(10, 2) NOT NULL,
 37	                refund DECIMAL(10, 2)
 38	            );
 39	
 40	            CREATE TABLE IF NOT EXISTS messages (
 41	                id BIGSERIAL PRIMARY KEY,
 42	                channel VARCHAR(20) NOT NULL,
 43	                recipient VARCHAR(255) NOT NULL,
 44	                subject VARCHAR(500) NOT NULL,
 45	                body TEXT NOT NULL,
 46	                status VARCHAR(20) NOT NULL
 47	            );
 48	            """;
 49	
 50	        try (Connection conn = dataSource.getConnection();
 51	             Statement stmt = conn.createStatement()) {
 52	            stmt.execute(sql);
 53	        } catch (Exception e) {
 54	            throw new RuntimeException("Failed to initialize database", e);
 55	        }
 56	    }
 57	}
