 60	import com.pousadamarealta.domain.Message;
 61	import com.pousadamarealta.domain.MessageChannel;
 62	import com.pousadamarealta.domain.MessageStatus;
 63	
 64	import javax.sql.DataSource;
 65	import java.sql.*;
 66	import java.util.ArrayList;
 67	import java.util.List;
 68	
 69	public class MessageRepository {
 70	    private final DataSource dataSource;
 71	
 72	    public MessageRepository(DataSource dataSource) {
 73	        this.dataSource = dataSource;
 74	    }
 75	
 76	    public Message save(Message message) {
 77	        String sql = """
 78	            INSERT INTO messages (channel, recipient, subject, body, status)
 79	            VALUES (?, ?, ?, ?, ?)
 80	            """;
 81	
 82	        try (Connection conn = dataSource.getConnection();
 83	             PreparedStatement stmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
 84	
 85	            stmt.setString(1, message.getChannel().name());
 86	            stmt.setString(2, message.getTo());
 87	            stmt.setString(3, message.getSubject());
 88	            stmt.setString(4, message.getBody());
 89	            stmt.setString(5, message.getStatus().name());
 90	
 91	            stmt.executeUpdate();
 92	
 93	            try (ResultSet rs = stmt.getGeneratedKeys()) {
 94	                if (rs.next()) {
 95	                    long id = rs.getLong(1);
 96	                    return new Message(
 97	                        id,
 98	                        message.getChannel(),
 99	                        message.getTo(),
