330	    public List<Reservation> findByMonth(YearMonth month) {
331	        LocalDate start = month.atDay(1);
332	        LocalDate end = month.atEndOfMonth().plusDays(1);
333	
334	        String sql = """
335	            SELECT id, room_number, guest_name, guest_email, guest_cpf,
336	                   check_in, check_out, guests, rate_plan, status,
337	                   amount_paid, refund
338	            FROM reservations
339	            WHERE check_in >= ? AND check_in < ?
340	              AND (amount_paid > 0 OR refund > 0)
341	            ORDER BY check_in, id
342	            """;
343	
344	        List<Reservation> reservations = new ArrayList<>();
345	
346	        try (Connection conn = dataSource.getConnection();
347	             PreparedStatement stmt = conn.prepareStatement(sql)) {
348	
349	            stmt.setDate(1, Date.valueOf(start));
350	            stmt.setDate(2, Date.valueOf(end));
351	
352	            try (ResultSet rs = stmt.executeQuery()) {
353	                while (rs.next()) {
354	                    reservations.add(mapReservation(rs));
355	                }
356	            }
357	        } catch (Exception e) {
358	            throw new RuntimeException("Failed to find reservations by month", e);
359	        }
360	
361	        return reservations;
362	    }
